static BOOL IsComments(UIScrollView *v){if(![NSStringFromClass(v.class) isEqualToString:@"TFNTableView"])return NO;BOOL u=NO,c=NO;UIResponder *r=v;for(NSUInteger i=0;r&&i<40;i++,r=r.nextResponder){if([r isKindOfClass:UIViewController.class]){NSString *n=NSStringFromClass(r.class);if([n isEqualToString:@"T1URTViewController"])u=YES;if([n isEqualToString:@"T1ConversationContainerViewController"])c=YES;}}return u&&c;}
