static NSString *Snapshot(UIScrollView *t){UIView *treatment=DescendantNamed(t,@"XDesignSystem.ScrollEdgeTreatment");if(!treatment){for(UIView *s in t.subviews){treatment=DescendantNamed(s,@"XDesignSystem.ScrollEdgeTreatment");if(treatment)break;}}UIView *back=treatment?DescendantNamed(treatment,@"_TtCC5UIKit20ScrollEdgeEffectView12BackdropView"):nil;UIView *effect=treatment?DescendantNamed(treatment,@"_TtC5UIKit20ScrollEdgeEffectView"):nil;return [NSString stringWithFormat:@"offset=%.1f dragging=%d decel=%d tracking=%d treatment=%p effect=%p backdrop=%p filters treatment=%lu effect=%lu backdrop=%lu",t.contentOffset.y,t.dragging,t.decelerating,t.tracking,treatment,effect,back,(unsigned long)FilterCount(treatment.layer),(unsigned long)FilterCount(effect.layer),(unsigned long)FilterCount(back.layer)];}
static void AddEvent(NSString *kind,UIScrollView *t,CGFloat dy){if(!atomic_load(&gActive))return;double ts=CACurrentMediaTime()-gStart;[gEvents addObject:[NSString stringWithFormat:@"%7.3fs %@ dy=%+.2f %@",ts,kind,dy,Snapshot(t)]];}
static void HookSetContentOffset(id self,SEL cmd,CGPoint p){UIScrollView *t=(UIScrollView *)self;CGPoint old=t.contentOffset;if(gSetContentOffset)((void(*)(id,SEL,CGPoint))gSetContentOffset)(self,cmd,p);if(!atomic_load(&gActive)||![NSThread isMainThread]||!IsComments(t))return;CGFloat dy=p.y-old.y;CFTimeInterval now=CACurrentMediaTime();NSMutableDictionary *st=[gState objectForKey:t];if(!st){st=[@{@"dir":@0,@"last":@(now),@"moving":@NO} mutableCopy];[gState setObject:st forKey:t];}
NSInteger dir=(fabs(dy)<0.25)?0:(dy>0?1:-1);NSInteger prev=[st[@"dir"] integerValue];CFTimeInterval last=[st[@"last"] doubleValue];BOOL moving=[st[@"moving"] boolValue];if(dir!=0){if(!moving || now-last>0.12){AddEvent(@"SCROLL_START",t,dy);}else if(prev!=0&&dir!=prev){AddEvent(@"DIRECTION_CHANGE",t,dy);}st[@"dir"]=@(dir);st[@"moving"]=@YES;st[@"last"]=@(now);}else if(moving&&now-last>0.12){st[@"moving"]=@NO;AddEvent(@"SCROLL_STOP",t,dy);} }
