static NSString *BuildReport(void){NSDictionary *i=NSBundle.mainBundle.infoDictionary;NSMutableString *r=[NSMutableString stringWithFormat:@"============================================================\nXLiquidGlass Comments Direction Probe %@ - captura #%lu\nApp: %@ build %@ | bundle=%@\nEventos=%lu\n============================================================\n",kVersion,(unsigned long)gSerial,i[@"CFBundleShortVersionString"]?:@"-",i[@"CFBundleVersion"]?:@"-",NSBundle.mainBundle.bundleIdentifier?:@"-",(unsigned long)gEvents.count];for(NSString *e in gEvents)[r appendFormat:@"%@\n",e];[r appendString:@"============================================================\n"];return r;}
static UIViewController *TopVC(void){UIWindow *w=nil;for(UIScene *s in UIApplication.sharedApplication.connectedScenes)if([s isKindOfClass:UIWindowScene.class])for(UIWindow *x in ((UIWindowScene *)s).windows)if(x.isKeyWindow){w=x;break;}UIViewController *v=w.rootViewController;while(1){UIViewController *n=v.presentedViewController;if(!n&&[v isKindOfClass:UINavigationController.class])n=((UINavigationController*)v).topViewController;if(!n&&[v isKindOfClass:UITabBarController.class])n=((UITabBarController*)v).selectedViewController;if(!n||n==v)break;v=n;}return v;}
static void Finish(void){if(!atomic_exchange(&gActive,false))return;gLast=BuildReport();[gLast writeToFile:ReportPath() atomically:YES encoding:NSUTF8StringEncoding error:nil];UIPasteboard.generalPasteboard.string=gLast;UIViewController *v=TopVC();if(v){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Direction Probe" message:@"Captura concluida e copiada." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"OK" style:UIAlertActionStyleDefault handler:nil]];[v presentViewController:a animated:YES completion:nil];}}
