-(void)viewDidLoad{[super viewDidLoad];self.title=@"Direction Probe";}
-(NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return 2;}
-(NSString*)tableView:(UITableView*)t titleForFooterInSection:(NSInteger)s{return @"Volte aos comentarios e faca: parado -> deslize -> inverta -> inverta novamente. Repita por 15 s.";}
-(UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)p{UITableViewCell*c=[t dequeueReusableCellWithIdentifier:@"x"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"x"];c.textLabel.text=p.row?@"Copiar relatorio":@"Iniciar diagnostico";return c;}
-(void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)p{[t deselectRowAtIndexPath:p animated:YES];if(p.row){NSString*x=gLast.length?gLast:[NSString stringWithContentsOfFile:ReportPath() encoding:NSUTF8StringEncoding error:nil];if(x.length)UIPasteboard.generalPasteboard.string=x;return;}UIAlertController*a=[UIAlertController alertControllerWithTitle:@"Direction Probe" message:@"Voce tera 8 segundos. Depois alterne a direcao varias vezes por 15 segundos." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"Cancelar" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"Comecar" style:UIAlertActionStyleDefault handler:^(__unused UIAlertAction*x){gArmed=YES;dispatch_after(dispatch_time(DISPATCH_TIME_NOW,8*NSEC_PER_SEC),dispatch_get_main_queue(),^{Begin();});}]];[self presentViewController:a animated:YES completion:nil];}
