static void Install(void){Class t=NSClassFromString(@"TFNTableView");if(t&&!gSetContentOffset)Hook(t,@selector(setContentOffset:),(IMP)HookSetContentOffset,&gSetContentOffset);Class s=NSClassFromString(@"ModernSettingsViewController");if(s){class_addMethod(s,NSSelectorFromString(@"showXLiquidGlassDirectionProbe"),(IMP)Show,"v@:");if(!gSettingsSetup)Hook(s,NSSelectorFromString(@"setupSections"),(IMP)SSetup,&gSettingsSetup);if(!gSettingsWillAppear)Hook(s,@selector(viewWillAppear:),(IMP)SWill,&gSettingsWillAppear);}}
